const COPPER = "#d69771";
const SILVER = "#aba7a8";
const BLUISH = "#456FA1";
const GOLD = "#c7a24a";


export class StarfleetAcademyUniformPack extends BaseTngEraUniformPack implements IUniformPack {

    constructor() {
        super(UniformEra.StarfleetAcademy);
    }

    getUniformSwatches() {
        return [
            new Swatch(BodyType.AverageMale, "Average Male", (token) => UniformCatalog.decorateSwatch(this.getUniformAndVariantByBodyType(token, UniformVariantType.Base, BodyType.AverageMale), BodyType.AverageMale, token), "BodyType.averageMale"),
            new Swatch(BodyType.AverageFemale, "Average Female", (token) => UniformCatalog.decorateSwatch(this.getUniformAndVariantByBodyType(token, UniformVariantType.Base, BodyType.AverageFemale), BodyType.AverageFemale, token), "BodyType.averageFemale")
        ];
    }

    getUniformVariantSwatches(token: TokenModel) {
        return [
            new Swatch(UniformVariantType.Base, "Base", (token) => UniformCatalog.decorateSwatch(this.getUniformAndVariantByBodyType(token, UniformVariantType.Base, token.bodyType), UniformVariantType.Base, token)),
            new Swatch(UniformVariantType.Variant1, "Grey Variant", (token) => UniformCatalog.decorateSwatch(this.getUniformAndVariantByBodyType(token, UniformVariantType.Variant1, token.bodyType), UniformVariantType.Variant1, token))
        ];
    }

    getUniformAndVariantBody(token: TokenModel) {
        return this.getUniformAndVariantByBodyType(token, token.variant, token.bodyType);
    }

    getUniformAndVariantByBodyType(token: TokenModel, variant: UniformVariantType, bodyType: BodyType) {
        let base = "";
        let divisionColour = token.divisionColor;
        if (bodyType === BodyType.AverageMale) {
            base = StarfleetAcademyUniform.maleBody;
        } else {
            base = StarfleetAcademyUniform.femaleBody;
        }

        if (token.rankIndicator === Rank.Captain) {
            if (bodyType === BodyType.AverageMale) {
                base += StarfleetAcademyUniform.maleBodyCaptainsVariant;
            } else {
                base += StarfleetAcademyUniform.femaleBodyCaptainsVariant;
            }
        }

        if (variant === UniformVariantType.Variant1) {
            base = base.replace(DefaultRed, "#808889").replace(/#2c2c2c/g, divisionColour).replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
        } else {
            base = base.replace(DefaultRed, divisionColour).replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
        }
        let metalHighlights = COPPER
        if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Command') {
            metalHighlights = COPPER;
        } else if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Science') {
            metalHighlights = BLUISH;
        } else if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Operations') {
            metalHighlights = GOLD;
        } else if (DivisionColors.getDivision(this.era, token.divisionColor) === 'Medical') {
            metalHighlights = SILVER;
        }

        base = base.replace(/#d69771/g, metalHighlights);

        return this.getNeck(bodyType, token.skinColor, token.species, UniformEra.DominionWar) + base;

    }

    getRankIndicator(token: TokenModel) {
        return "";
    }

    getBorderLogo(token: TokenModel): string {
        return borderInsignia;
    }

    getBorderColor(token: TokenModel): string {
        return token.divisionColor;
    }

    getRankBorderIndicator(token: TokenModel): string {
        return rankIndicators.border[Rank[token.rankIndicator]] ?? "";
    }
}